descriptor.controllerScript:
let alarmFetched = false, alarms = [], markers = [], intervalId;

self.onInit = function() {
    let now = moment();

    console.log(now)

    intervalId = setInterval(() => {
        if(!alarmFetched){
            alarms = [];
            markers = [];
            self.ctx.data.forEach(x=>{
                if(x.dataKey.name == "alertTelemetry"){
                    x.data.forEach(y=>{
                        if(y[1] && JSON.parse(y[1])){
                            let alarm = JSON.parse(y[1]);
                            alarms.push({
                                ts: y[0],
                                message: alarm.type,
                                latitude: alarm.latitude,
                                longitude: alarm.longitude,
                                isDrawed: false
                            });
                        }
                    });
                }
            });

            alarmFetched = true;
        }
        drawAlarm(self.ctx.mapInstance.polylines.get(self.ctx.datasources[0].entityName).data.time, alarms);
    }, 500);
}

function drawAlarm(time, alarms){
    alarms.forEach((alarm, index)=>{
        if(alarm.ts < time){
            if(!alarm.isDrawed){
                drawMarker(alarm.latitude, alarm.longitude, alarm.message, self.ctx.mapInstance.map);
                alarm.isDrawed = true;
            }
        } else {
            alarm.isDrawed = false;
            findAndDeleteMarker(alarm.latitude, alarm.longitude);
        }
    });
}

function findAndDeleteMarker(lat, lng) {
    const targetLatLng = L.latLng(lat, lng);

    for (let i = 0; i < markers.length; i++) {
        if (markers[i].getLatLng().equals(targetLatLng)) {
            markers[i].removeFrom(self.ctx.mapInstance.map);
            markers.splice(i, 1);
        }
    }

    return false;
}

function drawMarker(lat, lng, popupText, map){
    const customIcon = L.icon({
        iconUrl: icon, 
        iconSize: [26, 26], 
        iconAnchor: [13, 26], 
        popupAnchor: [0, -26]
    });

    const marker = L.marker([lat, lng], { icon: customIcon }).addTo(map);

    markers.push(marker);

    // if (popupText) {
    //     marker.bindPopup(popupText).openPopup();
    // }
}

self.actionSources = function() {
    return {
        'tooltipAction': {
            name: 'widget-action.tooltip-tag-action',
            multiple: false
        }
    }
};

self.typeParameters = function() {
    return {
        hasDataPageLink: true,
        ignoreDataUpdateOnIntervalTick: true,
        hasAdditionalLatestDataKeys: true
    };
};

self.onDestroy = function() {
    if (intervalId) {
        clearInterval(intervalId);
        intervalId = null;
    }
}

let icon = `data:image/jpeg;base64,`;
